import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.BWuWLRhz.js";const v=JSON.parse('{"title":"🔌 yutto server 连接断开 / 启动失败","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/serve-restart.md","filePath":"troubleshooting/serve-restart.md","lastUpdated":1784342610000}'),s={name:"troubleshooting/serve-restart.md"};function l(i,e,n,u,c,d){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="🔌-yutto-server-连接断开-启动失败" tabindex="-1">🔌 yutto server 连接断开 / 启动失败 <a class="header-anchor" href="#🔌-yutto-server-连接断开-启动失败" aria-label="Permalink to &quot;🔌 yutto server 连接断开 / 启动失败&quot;">​</a></h1><h2 id="🔍-现象" tabindex="-1">🔍 现象 <a class="header-anchor" href="#🔍-现象" aria-label="Permalink to &quot;🔍 现象&quot;">​</a></h2><ul><li>解析或下载失败，控制台出现「与 yutto server 的连接已断开」；</li><li>或启动应用后提示 yutto server 启动失败，解析按钮一直不可用。</li></ul><h2 id="💡-原因" tabindex="-1">💡 原因 <a class="header-anchor" href="#💡-原因" aria-label="Permalink to &quot;💡 原因&quot;">​</a></h2><p>解析与下载由一个常驻后台的 yutto server 完成（随应用自动启动、随应用关闭退出）。 它可能因为 Python 环境损坏、被安全软件拦截或进程意外崩溃而离线。</p><h2 id="✅-解决" tabindex="-1">✅ 解决 <a class="header-anchor" href="#✅-解决" aria-label="Permalink to &quot;✅ 解决&quot;">​</a></h2><ol><li>打开 设置 → 环境状态，找到「yutto server」一行；</li><li>点「重启」，状态恢复为运行中即可继续解析 / 下载；</li><li>如果重启仍失败： <ul><li>检查同一页里 Python / uv 是否就绪，必要时重新同步环境（参考 <a href="/troubleshooting/uv-sync-failed.html">uv sync 安装失败</a>）；</li><li>到控制台页查看 <code>[serve]</code> 开头的日志，按报错内容排查。</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">这些是正常现象</p><p>切换工作目录、点「保存并重新检测」都会自动重启 server；下载任务住在 server 里， 所以重启会中断进行中的任务（设置页保存前会有提示）。</p></div>',8)])])}const _=t(s,[["render",l]]);export{v as __pageData,_ as default};
